     1→import { logger } from "@/lib/logger";
     2→import { faker } from "@faker-js/faker";
     3→import { nanoid } from "nanoid";
     4→import { prisma } from "../src/lib/prisma";
     5→
     6→// Set seed for reproducibility
     7→faker.seed(123);
     8→
     9→async function main() {
    10→  logger.info("🌱 Seeding database...");
    11→
    12→  // Create 10 users (mix of individual and professional)
    13→  const userCreatePromises = Array.from({ length: 10 }, async (_, index) => {
    14→    const email = faker.internet.email();
    15→    // First 6 users will potentially be professionals (org members)
    16→    // Last 4 users will be individuals
    17→    const accountType = index < 6 ? "individual" : "individual"; // Will be updated later for org members
    18→
    19→    return prisma.user.upsert({
    20→      where: { email },
    21→      update: {},
    22→      create: {
    23→        id: nanoid(11),
    24→        name: faker.person.fullName(),
    25→        email,
    26→        emailVerified: faker.datatype.boolean(0.8), // 80% chance of being verified
    27→        image: faker.image.avatar(),
    28→        accountType,
    29→        createdAt: faker.date.past(),
    30→        updatedAt: faker.date.recent(),
    31→      },
    32→    });
    33→  });
    34→
    35→  const users = await Promise.all(userCreatePromises);
    36→  users.forEach((user) => logger.info(`👤 Created user: ${user.name}`));
    37→
    38→  // Create 3 organizations
    39→  const memberPromises: Promise<unknown>[] = [];
    40→  const invitationPromises: Promise<unknown>[] = [];
    41→
    42→  // Prepare organization creation data
    43→  const orgData = Array.from({ length: 3 }, () => {
    44→    const orgName = faker.company.name();
    45→    const orgSlug = orgName.toLowerCase().replace(/[^a-z0-9]/g, "-");
    46→    return { orgName, orgSlug };
    47→  });
    48→
    49→  // Create all organizations first
    50→  const organizations = await Promise.all(
    51→    orgData.map(async ({ orgName, orgSlug }) =>
    52→      prisma.organization
    53→        .upsert({
    54→          where: { slug: orgSlug },
    55→          update: {},
    56→          create: {
    57→            id: nanoid(11),
    58→            name: orgName,
    59→            slug: orgSlug,
    60→            logo: faker.image.url(),
    61→            email: faker.internet.email(),
    62→            createdAt: faker.date.past(),
    63→          },
    64→        })
    65→        .then((org) => {
    66→          logger.info(`🏢 Created organization: ${org.name}`);
    67→          return org;
    68→        }),
    69→    ),
    70→  );
    71→
    72→  // Process members and invitations for each organization
    73→  organizations.forEach((organization) => {
    74→    const roleOptions = ["owner", "admin", "member"];
    75→
    76→    // Make sure each org has at least one owner
    77→    memberPromises.push(
    78→      prisma.member
    79→        .create({
    80→          data: {
    81→            id: nanoid(11),
    82→            organizationId: organization.id,
    83→            userId: users[0].id, // First user is always an owner
    84→            role: "owner",
    85→            createdAt: faker.date.past(),
    86→          },
    87→        })
    88→        .then(() =>
    89→          logger.info(
    90→            `👑 Added ${users[0].name} as OWNER to ${organization.name}`,
    91→          ),
    92→        ),
    93→    );
    94→
    95→    // Add 2-4 more random members to each org
    96→    const memberCount = faker.number.int({ min: 2, max: 4 });
    97→    const memberIndices = faker.helpers.uniqueArray(
    98→      () => faker.number.int({ min: 1, max: users.length - 1 }),
    99→      memberCount,
   100→    );
   101→
   102→    for (const index of memberIndices) {
   103→      const user = users[index];
   104→      const role = faker.helpers.arrayElement(roleOptions);
   105→
   106→      memberPromises.push(
   107→        prisma.member
   108→          .create({
   109→            data: {
   110→              id: nanoid(11),
   111→              organizationId: organization.id,
   112→              userId: user.id,
   113→              role,
   114→              createdAt: faker.date.past(),
   115→            },
   116→          })
   117→          .then(() =>
   118→            logger.info(
   119→              `👥 Added ${user.name} as ${role} to ${organization.name}`,
   120→            ),
   121→          ),
   122→      );
   123→    }
   124→  });
   125→
   126→  await Promise.all([...memberPromises, ...invitationPromises]);
   127→
   128→  // Update account types: users who are members of organizations should be professionals
   129→  logger.info("🔄 Updating account types based on organization memberships...");
   130→
   131→  const usersWithMemberships = await prisma.user.findMany({
   132→    where: {
   133→      members: {
   134→        some: {},
   135→      },
   136→    },
   137→    include: {
   138→      members: {
   139→        include: {
   140→          organization: {
   141→            select: { name: true },
   142→          },
   143→        },
   144→      },
   145→    },
   146→  });
   147→
   148→  const accountTypeUpdatePromises = usersWithMemberships.map(async (user) => {
   149→    if (user.accountType !== "professional") {
   150→      await prisma.user.update({
   151→        where: { id: user.id },
   152→        data: { accountType: "professional" },
   153→      });
   154→
   155→      const orgNames = user.members.map((m) => m.organization.name).join(", ");
   156→      logger.info(
   157→        `👔 Updated ${user.name} → professional (member of: ${orgNames})`,
   158→      );
   159→    }
   160→  });
   161→
   162→  await Promise.all(accountTypeUpdatePromises);
   163→
   164→  // Create sample properties
   165→  const propertiesData = Array.from({ length: 20 }, () => ({
   166→    id: nanoid(11),
   167→    externalId: faker.string.alphanumeric(10),
   168→    title: faker.lorem.words(5),
   169→    description: faker.lorem.paragraphs(2),
   170→    type: faker.helpers.arrayElement(["sale", "rental"]),
   171→    category: faker.helpers.arrayElement(["apartment", "house", "commercial"]),
   172→    price: faker.number.int({ min: 100000, max: 2000000 }),
   173→    surface: faker.number.int({ min: 20, max: 200 }),
   174→    rooms: faker.number.int({ min: 1, max: 8 }),
   175→    bedrooms: faker.number.int({ min: 1, max: 5 }),
   176→    address: faker.location.streetAddress(),
   177→    city: faker.location.city(),
   178→    postalCode: faker.location.zipCode(),
   179→    department: faker.location.county(),
   180→    region: faker.location.state(),
   181→    floor: faker.helpers.maybe(() => faker.number.int({ min: 0, max: 10 }), {
   182→      probability: 0.7,
   183→    }),
   184→    totalFloors: faker.helpers.maybe(
   185→      () => faker.number.int({ min: 1, max: 15 }),
   186→      { probability: 0.7 },
   187→    ),
   188→    energyClass: faker.helpers.arrayElement([
   189→      "A",
   190→      "B",
   191→      "C",
   192→      "D",
   193→      "E",
   194→      "F",
   195→      "G",
   196→    ]),
   197→    hasGarden: faker.datatype.boolean(0.3),
   198→    hasParking: faker.datatype.boolean(0.6),
   199→    hasLift: faker.datatype.boolean(0.4),
   200→    hasTerrace: faker.datatype.boolean(0.4),
   201→    hasBalcony: faker.datatype.boolean(0.7),
   202→    sourceUrl: faker.internet.url(),
   203→    sourceId: faker.string.alphanumeric(8),
   204→    publishedAt: faker.date.recent({ days: 30 }),
   205→  }));
   206→
   207→  const properties = await Promise.all(
   208→    propertiesData.map(async (propertyData) =>
   209→      prisma.property.create({
   210→        data: propertyData,
   211→      }),
   212→    ),
   213→  );
   214→
   215→  logger.info(`🏠 Created ${properties.length} properties`);
   216→
   217→  // Create favorites for some users
   218→  const favoritePromises = users.slice(0, 5).flatMap((user) =>
   219→    faker.helpers
   220→      .arrayElements(properties, { min: 2, max: 5 })
   221→      .map(async (property) =>
   222→        prisma.favorite.create({
   223→          data: {
   224→            id: nanoid(11),
   225→            userId: user.id,
   226→            propertyId: property.id,
   227→            status: faker.helpers.arrayElement([
   228→              "saved",
   229→              "visited",
   230→              "contacted",
   231→              "rejected",
   232→            ]),
   233→            priority: faker.helpers.arrayElement(["high", "medium", "low"]),
   234→            notes: faker.helpers.maybe(() => faker.lorem.sentences(2), {
   235→              probability: 0.6,
   236→            }),
   237→            pricePerSqm: Math.round(property.price / (property.surface ?? 50)),
   238→            confidenceScore: faker.number.int({ min: 50, max: 100 }),
   239→            createdAt: faker.date.recent({ days: 15 }),
   240→          },
   241→        }),
   242→      ),
   243→  );
   244→
   245→  const favorites = await Promise.all(favoritePromises);
   246→  logger.info(`⭐ Created ${favorites.length} favorites`);
   247→
   248→  // Create saved searches
   249→  const savedSearchPromises = users.slice(0, 3).map(async (user) =>
   250→    prisma.savedSearch.create({
   251→      data: {
   252→        id: nanoid(11),
   253→        userId: user.id,
   254→        name: faker.lorem.words(3),
   255→        criteria: {
   256→          types: ["sale"],
   257→          categories: ["apartment", "house"],
   258→          priceRange: {
   259→            min: faker.number.int({ min: 100000, max: 300000 }),
   260→            max: faker.number.int({ min: 500000, max: 1000000 }),
   261→          },
   262→          locations: [
   263→            {
   264→              city: faker.location.city(),
   265→              radius: faker.number.int({ min: 5, max: 20 }),
   266→            },
   267→          ],
   268→        },
   269→        frequency: faker.helpers.arrayElement(["realtime", "daily", "weekly"]),
   270→        createdAt: faker.date.recent({ days: 10 }),
   271→      },
   272→    }),
   273→  );
   274→
   275→  const savedSearches = await Promise.all(savedSearchPromises);
   276→  logger.info(`🔍 Created ${savedSearches.length} saved searches`);
   277→
   278→  // Create comparisons
   279→  const comparisonPromises = users.slice(0, 2).map(async (user) =>
   280→    prisma.comparison.create({
   281→      data: {
   282→        id: nanoid(11),
   283→        userId: user.id,
   284→        name: `Comparison ${faker.location.city()}`,
   285→        createdAt: faker.date.recent({ days: 5 }),
   286→      },
   287→    }),
   288→  );
   289→
   290→  const comparisons = await Promise.all(comparisonPromises);
   291→
   292→  // Add properties to comparisons
   293→  const comparisonPropertyPromises = comparisons.flatMap((comparison) =>
   294→    faker.helpers
   295→      .arrayElements(properties, { min: 2, max: 4 })
   296→      .map(async (property) =>
   297→        prisma.comparisonProperty.create({
   298→          data: {
   299→            id: nanoid(11),
   300→            comparisonId: comparison.id,
   301→            propertyId: property.id,
   302→            decision: faker.helpers.arrayElement(["go", "nogo", "negotiate"]),
   303→            notes: faker.helpers.maybe(() => faker.lorem.sentences(1), {
   304→              probability: 0.5,
   305→            }),
   306→          },
   307→        }),
   308→      ),
   309→  );
   310→
   311→  await Promise.all(comparisonPropertyPromises);
   312→  logger.info(`📊 Created ${comparisons.length} comparisons`);
   313→
   314→  // Final statistics
   315→  logger.info("\n📈 Final Statistics:");
   316→
   317→  const accountTypeStats = await prisma.user.groupBy({
   318→    by: ["accountType"],
   319→    _count: true,
   320→  });
   321→
   322→  logger.info("👥 Account Types:");
   323→  for (const stat of accountTypeStats) {
   324→    logger.info(`   ${stat.accountType}: ${stat._count} users`);
   325→  }
   326→
   327→  const orgMemberStats = await prisma.member.groupBy({
   328→    by: ["role"],
   329→    _count: true,
   330→  });
   331→
   332→  logger.info("🏢 Organization Roles:");
   333→  for (const stat of orgMemberStats) {
   334→    logger.info(`   ${stat.role}: ${stat._count} members`);
   335→  }
   336→
   337→  logger.info("✅ Seeding completed!");
   338→}
   339→
   340→main()
   341→  .catch((e) => {
   342→    logger.error("❌ Error seeding database:", e);
   343→    process.exit(1);
   344→  })
   345→  .finally(async () => {
   346→    await prisma.$disconnect();
   347→  });
   348→

