     1→"use server";
     2→
     3→import { auth } from "@/lib/auth";
     4→import { headers } from "next/headers";
     5→import { redirect } from "next/navigation";
     6→import { prisma } from "@/lib/prisma";
     7→import { revalidatePath } from "next/cache";
     8→import { moteurImmoClient } from "@/lib/moteurimmo";
     9→
    10→export type CreateFavoriteRequest = {
    11→  propertyId: string;
    12→  notes?: string;
    13→  priority?: "high" | "medium" | "low";
    14→};
    15→
    16→export type UpdateFavoriteRequest = {
    17→  id: string;
    18→  notes?: string;
    19→  status?: "saved" | "visited" | "contacted" | "rejected";
    20→  priority?: "high" | "medium" | "low";
    21→};
    22→
    23→export async function getFavoritesAction() {
    24→  const session = await auth.api.getSession({
    25→    headers: await headers(),
    26→  });
    27→
    28→  if (!session?.user.id) {
    29→    redirect("/auth/signin");
    30→  }
    31→
    32→  const favorites = await prisma.favorite.findMany({
    33→    where: {
    34→      userId: session.user.id,
    35→    },
    36→    include: {
    37→      property: true,
    38→    },
    39→    orderBy: {
    40→      createdAt: "desc",
    41→    },
    42→  });
    43→
    44→  return favorites;
    45→}
    46→
    47→export async function createFavoriteAction(request: CreateFavoriteRequest) {
    48→  console.debug(
    49→    "🔍 [Favorites] Creating favorite for property:",
    50→    request.propertyId,
    51→  );
    52→
    53→  const session = await auth.api.getSession({
    54→    headers: await headers(),
    55→  });
    56→
    57→  if (!session?.user.id) {
    58→    redirect("/auth/signin");
    59→  }
    60→
    61→  console.debug("🔍 [Favorites] User ID:", session.user.id);
    62→
    63→  // Check if property exists, if not create it
    64→  let property = await prisma.property.findUnique({
    65→    where: { externalId: request.propertyId },
    66→  });
    67→
    68→  console.debug("🔍 [Favorites] Property exists:", property ? "YES" : "NO");
    69→
    70→  if (!property) {
    71→    try {
    72→      console.debug("🔍 [Favorites] Creating new property in database...");
    73→      console.debug(
    74→        "🔍 [Favorites] Fetching property data from MoteurImmo API...",
    75→      );
    76→
    77→      // Récupérer les vraies données du bien via MoteurImmo API
    78→      const moteurImmoProperty = await moteurImmoClient.getListingById(
    79→        request.propertyId,
    80→      );
    81→      console.debug(
    82→        "✅ [Favorites] Property data fetched from MoteurImmo:",
    83→        moteurImmoProperty.title,
    84→      );
    85→
    86→      property = await prisma.property.create({
    87→        data: {
    88→          externalId: request.propertyId,
    89→          title: moteurImmoProperty.title,
    90→          description: moteurImmoProperty.description,
    91→          type: moteurImmoProperty.type,
    92→          category: moteurImmoProperty.category,
    93→          price: moteurImmoProperty.price,
    94→          surface: moteurImmoProperty.surface,
    95→          rooms: moteurImmoProperty.rooms,
    96→          bedrooms: moteurImmoProperty.bedrooms,
    97→          floor: moteurImmoProperty.floor,
    98→          totalFloors: moteurImmoProperty.totalFloors,
    99→          address: moteurImmoProperty.address ?? "",
   100→          city: moteurImmoProperty.city,
   101→          postalCode: moteurImmoProperty.postalCode ?? "",
   102→          department: "", // Required by Prisma schema
   103→          region: "", // Required by Prisma schema
   104→          energyClass: moteurImmoProperty.energyClass,
   105→          hasGarden: moteurImmoProperty.hasGarden,
   106→          hasParking: moteurImmoProperty.hasParking,
   107→          hasLift: moteurImmoProperty.hasLift,
   108→          hasTerrace: moteurImmoProperty.hasTerrace,
   109→          hasBalcony: moteurImmoProperty.hasBalcony,
   110→          sourceUrl: moteurImmoProperty.url,
   111→          sourceId: moteurImmoProperty.origin,
   112→          publishedAt: new Date(moteurImmoProperty.publishedAt),
   113→        },
   114→      });
   115→      console.debug("✅ [Favorites] Property created with ID:", property.id);
   116→    } catch (error) {
   117→      console.debug("❌ [Favorites] Error creating property:", error);
   118→      // Si l'API MoteurImmo échoue, créer un placeholder comme avant
   119→      console.debug(
   120→        "🔍 [Favorites] Fallback: Creating placeholder property...",
   121→      );
   122→      property = await prisma.property.create({
   123→        data: {
   124→          externalId: request.propertyId,
   125→          title: "Bien immobilier - Données en cours de chargement",
   126→          type: "sale",
   127→          category: "flat",
   128→          price: 0,
   129→          address: "Adresse en cours de chargement...",
   130→          city: "Ville inconnue",
   131→          postalCode: "00000",
   132→          department: "Département",
   133→          region: "Région",
   134→          publishedAt: new Date(),
   135→        },
   136→      });
   137→    }
   138→  }
   139→
   140→  // Check if already in favorites
   141→  const existingFavorite = await prisma.favorite.findUnique({
   142→    where: {
   143→      userId_propertyId: {
   144→        userId: session.user.id,
   145→        propertyId: property.id,
   146→      },
   147→    },
   148→  });
   149→
   150→  if (existingFavorite) {
   151→    throw new Error("Ce bien est déjà dans vos favoris");
   152→  }
   153→
   154→  const favorite = await prisma.favorite.create({
   155→    data: {
   156→      userId: session.user.id,
   157→      propertyId: property.id,
   158→      notes: request.notes,
   159→      priority: request.priority ?? "medium",
   160→    },
   161→    include: {
   162→      property: true,
   163→    },
   164→  });
   165→
   166→  console.debug(
   167→    `✅ [Favorites] Added property ${property.id} to favorites for user ${session.user.id}`,
   168→  );
   169→
   170→  revalidatePath("/favorites");
   171→  revalidatePath("/properties");
   172→  revalidatePath("/orgs", "layout");
   173→
   174→  return favorite;
   175→}
   176→
   177→export async function updateFavoriteAction(request: UpdateFavoriteRequest) {
   178→  const session = await auth.api.getSession({
   179→    headers: await headers(),
   180→  });
   181→
   182→  if (!session?.user.id) {
   183→    redirect("/auth/signin");
   184→  }
   185→
   186→  const favorite = await prisma.favorite.findFirst({
   187→    where: {
   188→      id: request.id,
   189→      userId: session.user.id,
   190→    },
   191→  });
   192→
   193→  if (!favorite) {
   194→    throw new Error("Favori non trouvé");
   195→  }
   196→
   197→  const updatedFavorite = await prisma.favorite.update({
   198→    where: {
   199→      id: request.id,
   200→    },
   201→    data: {
   202→      ...(request.notes !== undefined && { notes: request.notes }),
   203→      ...(request.status && { status: request.status }),
   204→      ...(request.priority && { priority: request.priority }),
   205→    },
   206→    include: {
   207→      property: true,
   208→    },
   209→  });
   210→
   211→  console.debug(
   212→    `✅ [Favorites] Updated favorite ${request.id} for user ${session.user.id}`,
   213→  );
   214→
   215→  revalidatePath("/favorites");
   216→
   217→  return updatedFavorite;
   218→}
   219→
   220→export async function deleteFavoriteAction(id: string) {
   221→  const session = await auth.api.getSession({
   222→    headers: await headers(),
   223→  });
   224→
   225→  if (!session?.user.id) {
   226→    redirect("/auth/signin");
   227→  }
   228→
   229→  const favorite = await prisma.favorite.findFirst({
   230→    where: {
   231→      id,
   232→      userId: session.user.id,
   233→    },
   234→  });
   235→
   236→  if (!favorite) {
   237→    throw new Error("Favori non trouvé");
   238→  }
   239→
   240→  await prisma.favorite.delete({
   241→    where: {
   242→      id,
   243→    },
   244→  });
   245→
   246→  console.debug(
   247→    `✅ [Favorites] Deleted favorite ${id} for user ${session.user.id}`,
   248→  );
   249→
   250→  revalidatePath("/favorites");
   251→  revalidatePath("/properties");
   252→  revalidatePath("/orgs", "layout");
   253→}
   254→
   255→export async function toggleFavoriteAction(
   256→  propertyExternalId: string,
   257→): Promise<{ isFavorite: boolean }> {
   258→  console.debug(
   259→    "🔍 [Favorites] Toggle favorite for property:",
   260→    propertyExternalId,
   261→  );
   262→
   263→  const session = await auth.api.getSession({
