     1→"use client";
     2→
     3→import { create } from "zustand";
     4→import { persist } from "zustand/middleware";
     5→import type { ComparisonProperty } from "./types";
     6→
     7→type ComparisonStore = {
     8→  properties: ComparisonProperty[];
     9→  addProperty: (property: ComparisonProperty) => void;
    10→  removeProperty: (propertyId: string) => void;
    11→  clearAll: () => void;
    12→  hasProperty: (propertyId: string) => boolean;
    13→  getPropertyCount: () => number;
    14→};
    15→
    16→export const useComparisonStore = create<ComparisonStore>()(
    17→  persist(
    18→    (set, get) => ({
    19→      properties: [],
    20→
    21→      addProperty: (property) => {
    22→        const { properties } = get();
    23→        if (properties.some((p) => p.uniqueId === property.uniqueId)) {
    24→          return; // Property already in comparison
    25→        }
    26→
    27→        // Limit to maximum 4 properties for better comparison
    28→        if (properties.length >= 4) {
    29→          return;
    30→        }
    31→
    32→        set({ properties: [...properties, property] });
    33→      },
    34→
    35→      removeProperty: (propertyId) => {
    36→        const { properties } = get();
    37→        set({
    38→          properties: properties.filter((p) => p.uniqueId !== propertyId),
    39→        });
    40→      },
    41→
    42→      clearAll: () => {
    43→        set({ properties: [] });
    44→      },
    45→
    46→      hasProperty: (propertyId) => {
    47→        const { properties } = get();
    48→        return properties.some((p) => p.uniqueId === propertyId);
    49→      },
    50→
    51→      getPropertyCount: () => {
    52→        return get().properties.length;
    53→      },
    54→    }),
    55→    {
    56→      name: "choosewisely-comparison",
    57→    },
    58→  ),
    59→);
