    28→
    29→export function ComparisonTable({
    30→  properties,
    31→  onRemoveProperty,
    32→  onClearAll,
    33→  onExportPDF,
    34→}: ComparisonTableProps) {
    35→  const [highlightBest, setHighlightBest] = useState(true);
    36→
    37→  if (properties.length === 0) {
    38→    return (
    39→      <Card>
    40→        <CardContent className="flex flex-col items-center justify-center py-12">
    41→          <p className="text-muted-foreground">
    42→            Aucun bien sélectionné pour la comparaison
    43→          </p>
    44→          <p className="text-muted-foreground mt-2 text-sm">
    45→            Ajoutez des biens depuis la recherche pour les comparer
    46→          </p>
    47→        </CardContent>
    48→      </Card>
    49→    );
    50→  }
    51→
    52→  const formatValue = (value: unknown, type: string): string => {
    53→    if (value === null || value === undefined) return "N/A";
    54→
    55→    switch (type) {
    56→      case "currency":
    57→        return new Intl.NumberFormat("fr-FR", {
    58→          style: "currency",
    59→          currency: "EUR",
    60→          minimumFractionDigits: 0,
    61→        }).format(value as number);
    62→      case "surface":
    63→        return `${value} m²`;
    64→      case "energy":
    65→        return value as string;
    66→      case "number":
    67→        return value.toString();
    68→      case "boolean":
    69→        return (value as boolean) ? "Oui" : "Non";
    70→      default:
    71→        return value.toString();
    72→    }
    73→  };
    74→
    75→  const getBestValue = (metric: ComparisonMetric, values: unknown[]) => {
    76→    const validValues = values.filter((v) => v !== null && v !== undefined);
    77→    if (validValues.length === 0) return null;
    78→
    79→    switch (metric.type) {
    80→      case "currency":
    81→        return Math.min(...(validValues as number[]));
    82→      case "surface":
    83→      case "number":
    84→        return Math.max(...(validValues as number[]));
    85→      case "energy": {
    86→        const energyOrder = ["A", "B", "C", "D", "E", "F", "G"];
    87→        return validValues.reduce((best, current) => {
    88→          const bestIndex = energyOrder.indexOf(best as string);
    89→          const currentIndex = energyOrder.indexOf(current as string);
    90→          return currentIndex < bestIndex || bestIndex === -1 ? current : best;
    91→        });
    92→      }
    93→      default:
    94→        return null;
    95→    }
    96→  };
    97→
    98→  const isHighlighted = (
    99→    value: unknown,
   100→    metric: ComparisonMetric,
   101→    allValues: unknown[],
   102→  ) => {
   103→    if (!highlightBest || value === null || value === undefined) return false;
   104→    const bestValue = getBestValue(metric, allValues);
   105→    return value === bestValue;
   106→  };
   107→
   108→  return (
   109→    <Card>
   110→      <CardHeader>
   111→        <div className="flex items-center justify-between">
   112→          <CardTitle>Comparaison de biens ({properties.length})</CardTitle>
   113→          <div className="flex items-center gap-2">
   114→            <Button
