   120→            </Button>
   121→            {onExportPDF && (
   122→              <Button variant="outline" size="sm" onClick={onExportPDF}>
   123→                <FileText className="mr-2 h-4 w-4" />
   124→                Export PDF
   125→              </Button>
   126→            )}
   127→            <Button variant="outline" size="sm" onClick={onClearAll}>
   128→              <Trash2 className="mr-2 h-4 w-4" />
   129→              Tout effacer
   130→            </Button>
   131→          </div>
   132→        </div>
   133→      </CardHeader>
   134→      <CardContent>
   135→        <div className="overflow-x-auto">
   136→          <Table>
   137→            <TableHeader>
   138→              <TableRow>
   139→                <TableHead className="bg-background sticky left-0 w-48">
   140→                  Critère
   141→                </TableHead>
   142→                {properties.map((property) => (
   143→                  <TableHead key={property.uniqueId} className="min-w-[200px]">
   144→                    <div className="flex items-start justify-between gap-2">
   145→                      <div className="min-w-0 flex-1">
   146→                        <div className="relative mb-2 aspect-video overflow-hidden rounded">
   147→                          <SafeImage
   148→                            src={property.mainImage ?? property.images[0]}
   149→                            alt={property.title}
   150→                            fill
   151→                            className="object-cover"
   152→                          />
   153→                        </div>
   154→                        <p className="truncate text-sm font-medium">
   155→                          {property.title}
   156→                        </p>
   157→                        <p className="text-muted-foreground text-xs">
   158→                          {property.city}
   159→                        </p>
   160→                      </div>
   161→                      <Button
   162→                        variant="ghost"
   163→                        size="sm"
   164→                        onClick={() => onRemoveProperty(property.uniqueId)}
   165→                        className="h-6 w-6 flex-shrink-0 p-0"
   166→                      >
   167→                        <X className="h-4 w-4" />
   168→                      </Button>
   169→                    </div>
   170→                  </TableHead>
   171→                ))}
   172→              </TableRow>
   173→            </TableHeader>
   174→            <TableBody>
   175→              {COMPARISON_METRICS.map((metric) => {
   176→                const values = properties.map(
   177→                  (property) => property[metric.key],
   178→                );
   179→
   180→                return (
   181→                  <TableRow key={metric.key}>
   182→                    <TableCell className="bg-background sticky left-0 font-medium">
