   186→                      )}
   187→                    </TableCell>
   188→                    {properties.map((property, index) => {
   189→                      const value = values[index];
   190→                      const isHighlight = isHighlighted(value, metric, values);
   191→
   192→                      return (
   193→                        <TableCell
   194→                          key={property.uniqueId}
   195→                          className={
   196→                            isHighlight && highlightBest
   197→                              ? "border border-green-200 bg-green-50 font-medium text-green-700"
   198→                              : ""
   199→                          }
   200→                        >
   201→                          {formatValue(value, metric.type)}
   202→                        </TableCell>
   203→                      );
   204→                    })}
   205→                  </TableRow>
   206→                );
   207→              })}
   208→            </TableBody>
   209→          </Table>
   210→        </div>
